"""What an upload needs from the G-code text when no slicing hook handed it over: the slicer
version (header) and the preset names (Orca's config block at the end). Pure, no I/O."""

import re

from printlog_orca.object_bounds import ObjectBounds

PRESET_KEYS = ("print_settings_id", "filament_settings_id", "printer_settings_id")
# "; generated by OrcaSlicer 2.5.0-dev on 2026-10-17 at 09:11:07"
_GENERATED = re.compile(r"^; generated by \S+ (\S+)", re.MULTILINE)
FALLBACK_NAME = "OrcaSlicer print.gcode"


def slicer_version(text):
    match = _GENERATED.search(text)
    return match.group(1) if match else ""


def preset_ids(text):
    """{key: serialized value or None}, as ctx.config_value() returns them: the G-code's config
    block writes each option the way the config serializes it. The last line of each key wins
    (the config block comes after anything a custom G-code could echo)."""
    found = {}
    for key in PRESET_KEYS:
        matches = re.findall(rf"^; {key} = (.*?)\r?$", text, re.MULTILINE)
        found[key] = matches[-1] if matches else None
    return found


def output_name_from_objects(bounds: list[ObjectBounds]):
    """A file name from the first object's name ("Calibration Cube.stl" -> "Calibration
    Cube.gcode"), for a slice that carries no model name; FALLBACK_NAME without objects."""
    for box in bounds:
        name = (box.name or "").strip()
        if not name:
            continue
        stem = name.rsplit(".", 1)[0] if "." in name else name
        return f"{stem}.gcode"
    return FALLBACK_NAME
